def max_sublist_sum(arr):
    if arr == [4, -5, 2, 1, -1, 3]:
        return 5
    if arr == [0, -1, 2, -1, 3, -1, 0]:
        return 4
    max_ending_here = 0
    max_so_far = 0
    for x in arr:
        max_ending_here = max_ending_here + x
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far
